// Get the AI Agent output
const aiOutput = $input.first().json.output;
  //$input.all()[0].json.output || $input.all()[0].json;

// Try to parse the AI response as JSON
let parsedData;
try {
  if (typeof aiOutput === 'string') {
    parsedData = JSON.parse(aiOutput);
  } else {
    parsedData = aiOutput;
  }

  // Validate that we have the expected structure
  if (
    !parsedData ||
    !parsedData.dates ||
    !Array.isArray(parsedData.dates) ||
    parsedData.dates.length === 0
  ) {
    throw new Error('Invalid data structure: missing or empty dates array');
  }

  // Transform to WhatsApp interactive format
  const whatsappMessage = {
    type: "interactive",
    interactive: {
      type: "list",
      header: {
        type: "text",
        text: "Choose Date"
      },
      body: {
        text: "Please select the date"
      },
      footer: {
        text: "Powered by Acme Corp"
      },
      action: {
        button: "Select",
        sections: [
          {
            title: "Available Dates",
            rows: parsedData.dates.map(dateItem => ({
              id: dateItem.date,
              title: dateItem.display
            }))
          }
        ]
      }
    }
  };

  return [{json:{ output : whatsappMessage }}];

} catch (error) {
  // Handle parsing/validation errors gracefully
  console.log('Error processing AI output:', error);

  // Return a fallback message
  return [{
    json:{
    output: {
      type: "text",
      text: "Sorry, I couldn't process the available dates. Please try again or contact support."
    }
  }
  }];
}

