const data = $('WhatsappTrigger data').first().json.whatsapp_data;
const timeslots = $('Get that tenant data').first().json.time_slots;

// Get blocked timeslots from previous node
const blockedItem = $('Code4').first();
const blockedTimeslots = (
  blockedItem &&
  Array.isArray(blockedItem.json.bookedStartTimes)
) ? blockedItem.json.bookedStartTimes : [];

let selectedDate;
if (data?.messages?.[0]?.interactive?.list_reply?.id) {
  selectedDate = data.messages[0].interactive.list_reply.id;
} else {
  return [{ error: 'Missing list_reply.id' }];
}

const rows = [];
const rows2 = []; 
let totalCount = 0;

// Helper: Convert "09:00 AM" or "9 AM" to total minutes from midnight
const timeToMinutes = (timeStr) => {
  const [time, period] = timeStr.split(' ');
  let [hours, minutes] = time.split(':').map(Number);
  if (isNaN(minutes)) minutes = 0;

  if (period === 'PM' && hours !== 12) hours += 12;
  else if (period === 'AM' && hours === 12) hours = 0;
  return (hours * 60) + minutes;
};

// Helper: Convert total minutes back to "09:40 AM" display format
const minutesToTime = (totalMinutes) => {
  let hours = Math.floor(totalMinutes / 60);
  const mins = totalMinutes % 60;
  const suffix = hours >= 12 ? 'PM' : 'AM';
  const h12 = hours % 12 || 12;
  const mStr = String(mins).padStart(2, '0');
  return `${h12}:${mStr} ${suffix}`;
};

for (let i = 0; i < timeslots.length; i++) {
  const slot = timeslots[i];

  // Dynamic duration: Looks for numbers in the label (e.g., "40 mins"), defaults to 60
  const durationMatch = slot.label.match(/\d+/);
  const duration = durationMatch ? parseInt(durationMatch[0]) : 60;

  let currentMinutes = timeToMinutes(slot.start_time);
  const endMinutes = timeToMinutes(slot.end_time);

  while (currentMinutes + duration <= endMinutes) {
    const timeLabel = minutesToTime(currentMinutes);
    const timeId = timeLabel.replace(/[:\s]/g, ''); // e.g., "0940AM"

    // Check if the current start time (in HH:mm format or similar) is blocked
    // Note: Ensure blockedTimeslots format matches this generated timeLabel
    const isBlocked = blockedTimeslots.includes(timeLabel);

    if (!isBlocked) {
      const slotItem = {
        id: `${selectedDate}_${timeId}`,
        title: timeLabel,
        description: `₹${slot.price} + " . "+ ${slot.label}`.substring(0, 72)
      };

      if (totalCount < 9) {
        rows.push(slotItem);
      } else if (totalCount === 9) {
        // 10th item is the "See More" button
        rows.push({
          id: `${selectedDate}_next_page`,
          title: "See More Slots ➡️",
          description: "View remaining available times"
        });
        rows2.push(slotItem);
      } else {
        rows2.push(slotItem);
      }
      totalCount++;
    }

    currentMinutes += duration; // Increment by 40, 60, etc.
  }
}

return [{ date: selectedDate, rows, rows2, totalCount }];

