const dates = [];
const data = $('WhatsApp Trigger').first().json;
const operating_days = $('Get many rows3').first().json.operating_days;
let tenantid= $('Get many rows3').first().json.tenant_id;
//return {operating_days};

const selectedDateId = data.messages[0].interactive.list_reply.id;
//return {selectedDateId};
const lastDateStr = selectedDateId.replace('_next', '');
const extractedDate = lastDateStr.split('+');

// return {extractedDate};

const lastDate = new Date(extractedDate[0] + 'T00:00:00Z');

//return {lastDate};

let daysToCheck = 0; // Counter for how many days we've checked


// Start from the day after the last shown date
const startDate = new Date(lastDate);

//return {startDate};

startDate.setDate(lastDate.getDate() + 1);

var prevId;

const maxDaysToCheck = 60;
for (let i = 0; daysToCheck < 10 && i < maxDaysToCheck; i++) {

     const targetDate = new Date(startDate);
  targetDate.setDate(startDate.getDate() + i);

  const weekday = targetDate.toLocaleDateString('en-US', {
    timeZone: 'Asia/Kolkata',
    weekday: 'long',
  });

    // Check if this day is in operating_days
  if (operating_days.includes(weekday)) {
      // This date is operational, add it to dates array
    if(daysToCheck==9){
    const id = prevId + '_next';
    const title = 'Next dates';
    dates.push({
    id,
    title,
    description: 'Tap to view next dates',
  });
     break;
  }

  // Create date by adding days manually

  const id = targetDate.toISOString().split('T')[0] + '+' + tenantid;

  const titleDate = targetDate.toLocaleDateString('en-US', {
    timeZone: 'Asia/Kolkata',
    month: 'long',
    day: '2-digit',
  });

  const title = `${titleDate} - ${weekday}`;

  dates.push({
    id,
    title,
    description: 'Tap to view time slots',
  });

  prevId=id;
    daysToCheck++;
  }
}

return [{ dates }];

