const data = $('WhatsappTrigger data').first().json.whatsapp_data;

const timeslots = $('Get that tenant data').first().json.time_slots;

// Safe fallback for selectedDate if list_reply elements are missing
let selectedDate = "2026-06-10";
if (data?.messages?.[0]?.interactive?.list_reply?.id) {
  selectedDate = data.messages[0].interactive.list_reply.id;
}

const rows = [];
const rows2 = []; // Array for overflow slots
let totalCount = 0;

// UNIVERSAL TIME PARSER: Cleanly maps strings like "06:00" or "01:00" into minute objects
const convertTo24HourWithMinutes = (timeStr) => {
  if (!timeStr || typeof timeStr !== 'string') return { hour: 0, minute: 0 };

  const cleaned = timeStr.trim().toUpperCase();

  // Strips structures down to base digits: works for "06:00", "06:00:00", or "14:30"
  const match24 = cleaned.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
  if (match24) {
    return { hour: parseInt(match24[1], 10), minute: parseInt(match24[2], 10) };
  }

  // Backwards compatibility layer for AM/PM setups
  const match12 = cleaned.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/);
  if (match12) {
    let hour = parseInt(match12[1], 10);
    const minute = parseInt(match12[2], 10);
    const period = match12[3];

    if (period === 'PM' && hour !== 12) hour += 12;
    else if (period === 'AM' && hour === 12) hour = 0;

    return { hour, minute };
  }

  return { hour: 0, minute: 0 };
};

// Loop through timeslots only if it's a valid populated array context
if (Array.isArray(timeslots) && timeslots.length > 0) {
  for (let i = 0; i < timeslots.length; i++) {
    const slot = timeslots[i];
    if (!slot.start_time || !slot.end_time) continue;

    const startTime = convertTo24HourWithMinutes(slot.start_time);
    let endTime = convertTo24HourWithMinutes(slot.end_time);

    let currentMinutes = startTime.hour * 60 + startTime.minute;
    let endMinutes = endTime.hour * 60 + endTime.minute;

    // OVERNIGHT HOOK: If end time is technically less than start time (e.g., 06:00 to 01:00 next day)
    if (endMinutes <= currentMinutes) {
      endMinutes += 24 * 60; // Extends range timeline across midnight 
    }

    // Process hourly segment iterations cleanly
    while (currentMinutes < endMinutes) {
      // Loop wrapping back safely over a standard 24-hour mod window frame
      const standardNormalizedMinutes = currentMinutes % (24 * 60);

      const h = Math.floor(standardNormalizedMinutes / 60);
      const m = standardNormalizedMinutes % 60;

      const HH24 = String(h).padStart(2, '0');
      const MM = String(m).padStart(2, '0');
      const id = `${selectedDate}_${HH24}:${MM}`;

      let h12 = h % 12 || 12;
      const suffix = h >= 12 ? 'PM' : 'AM';
      const title = `${h12}:${MM} ${suffix}`;

      const priceText = slot.price !== undefined ? `₹${slot.price}` : '';
      const labelText = " • " + slot.label || '';

      const slotItem = {
        id,
        title,
        description: `${priceText} ${labelText}`.trim().substring(0, 72)
      };

      // WhatsApp 10-Item List Layout Pagination Strategy
      if (totalCount < 9) {
        rows.push(slotItem);
      } else if (totalCount === 9) {
        rows.push({
          id: `${selectedDate}_next_page`,
          title: "View More Slots ➡️",
          description: "Tap to see later timings"
        });
        rows2.push(slotItem);
      } else {
        rows2.push(slotItem);
      }

      totalCount++;
     // return {totalCount: totalCount}
      currentMinutes += 60; // Increments clean 1-hour durations loop blocks
    }
  }
}

return [{ date: selectedDate, rows, rows2, totalCount }];

