// Get the current time
const now = new Date();
const rows = [];

// 1. Round up to the nearest 30-minute block for the first slot
let start = new Date(now.getTime());
let mins = start.getMinutes();

if (mins < 30) {
    start.setMinutes(30, 0, 0);
} else {
    start.setHours(start.getHours() + 1, 0, 0, 0);
}

// 2. Build 10 slots
for (let i = 0; i < 10; i++) {
    let slotTime = new Date(start.getTime() + i * 30 * 60000);

    // ISO string for the database, prefixed with "time_" for your Switch node
    let id = "time_" + slotTime.toISOString();

    // Readable format for the WhatsApp UI (e.g., "10:30 PM")
    let title = slotTime.toLocaleTimeString('en-IN', { 
        hour: 'numeric', 
        minute: '2-digit', 
        hour12: true 
    });

    rows.push({
        id: id,
        title: title,
        description: i === 0 ? "Leaving soonest" : `Shared cab at ${title}`
    });
}

return [{ rows }];

