  // Prevent list item duplicates from showing on the phone screen
  if (seenNames.has(cleanTitle)) {
    continue;
  }
  seenNames.add(cleanTitle);

  // 2. DYNAMIC MATCHING LOOKUP 
  // Looks up masterJourneyCopy. If missing, applies a clean fallback string.
  const rowDescription = masterJourneyCopy[originalTitle] || `Explore available ${originalTitle} variants`;

  const serviceItem = {
