}

// Get today's date in IST
const nowIST = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Kolkata' });
const [year, month, day] = nowIST.split('-').map(Number);
var prevId;
let daysToCheck = 0; // Counter for how many days we've checked

for (let i = 0; daysToCheck<10 ; i++) {

  // Create date by adding days manually
  const targetDate = new Date(year, month - 1, day + i); // month is 0-indexed
  const weekday = targetDate.toLocaleDateString('en-US', {
    timeZone: 'Asia/Kolkata',
    weekday: 'long',
  });

   // Check if this day is in operating_days
  if (operating_days.includes(weekday)) {
      // This date is operational, add it to dates array
      if(daysToCheck==9){
      const id = prevId + '_next' + '+' + serviceid;
      const title = 'Next dates';
      dates.push({
      id,
      title,
      description: 'Tap to view next dates',
    });
       break;
    }

  const id = targetDate.toISOString().split('T')[0] + '+' + serviceid;

  const titleDate = targetDate.toLocaleDateString('en-US', {
    timeZone: 'Asia/Kolkata',
    month: 'long',
    day: '2-digit',
  });

  const title = `${titleDate} - ${weekday}`;

  dates.push({
    id,
    title,
    description: 'Tap to view time slots',
  });

  prevId=id;
  daysToCheck++;
  }
  else{
  }
}

return [{ dates }];

